/// Coverage for one character, or `None` when the font has no glyph.
#[must_use]
pub fn coverage(ch: char) -> Option<&'static [u8; CELL_BYTES]> {
    let code = u32::from(ch);
    let index = CODES.binary_search(&code).ok()?;
    COVERAGE.get(index)
}

